&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Homme-l&#233;zard&lt;div style=&quot;float:right;&quot;&gt;FP 1&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;humano&#239;de&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/humano&#239;de.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Marais&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Marais.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Temp&#233;r&#233;&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Temp&#233;r&#233;.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire&lt;/i&gt; p.182
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 400
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Reptilien.html&quot; title=&quot;Reptilien (sous-type)&quot;&gt;reptilien&lt;/a&gt;) de taille M, N
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +0 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +1
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 17, contact 10, pris au d&#233;pourvu 17 (bouclier +2, naturelle +5)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 11 (2d8+2)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +0, &lt;b&gt;Vig&lt;/b&gt; +4, &lt;b&gt;Vol&lt;/b&gt; +0
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), nage 4,50 m (3 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; morgenstern, +2 (1d8+1), morsure, +0 (1d4) ou griffe, +2 (1d4+1), morsure, +2 (1d4+1)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Distance&lt;/b&gt; javeline, +1 (1d6+1)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 13, &lt;b&gt;Dex&lt;/b&gt; 10, &lt;b&gt;Con&lt;/b&gt; 13, &lt;b&gt;Int&lt;/b&gt; 9, &lt;b&gt;Sag&lt;/b&gt; 10, &lt;b&gt;Cha&lt;/b&gt; 10
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +1, &lt;b&gt;BMO&lt;/b&gt; +2, &lt;b&gt;DMD&lt;/b&gt; 12
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-Multiples.html&quot; title=&quot;Attaques multiples&quot;&gt;Attaques multiples&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +2, &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; +8, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +1 ; &lt;b&gt;Modificateurs raciaux&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +4
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; draconique
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; retenir son souffle
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;&#201;cologie&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Environnement&lt;/b&gt; marais temp&#233;r&#233;s
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Organisation sociale&lt;/b&gt; solitaire, couple, groupe (3-12) ou tribu (13-60)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Tr&#233;sor&lt;/b&gt; &#233;quipement de PNJ (bouclier lourd en bois, morgenstern, 3 javelines)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Capacit&#233;s sp&#233;ciales&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Retenir son souffle (Ext)&lt;/b&gt; Un homme-l&#233;zard peut retenir sa respiration pendant un nombre de rounds &#233;gal &#224; 4 fois sa valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; avant de courir le risque de se noyer.
&lt;/div&gt;
&lt;/div&gt;&lt;br /&gt;
&lt;center&gt;&lt;img src=&quot;/wiki/public/upload/Bestiaire/Homme-l&#233;zard.jpg&quot; width=&quot;90%&quot; style=&quot;float: none; margin: 5px;&quot;/&gt;&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;i&gt;Cet humano&#239;de reptilien poss&#232;de des &#233;cailles vertes, un museau court dot&#233; de dangereuses dents et une longue queue d’alligator.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Les hommes-l&#233;zards sont de fiers et puissants pr&#233;dateurs
reptiliens dont les villages sont diss&#233;min&#233;s dans les profondeurs
des marais et des mar&#233;cages. Ils ne semblent pas vouloir coloniser
les terres plus s&#232;ches et se contentent des armes et des rituels
simples qu’ils emploient depuis des mill&#233;naires. &lt;br /&gt;&lt;br /&gt;De nombreuses races les consid&#232;rent comme des sauvages sans culture mais leurs
communaut&#233;s isol&#233;es abritent un peuple haut en couleurs, avec
des traditions et une histoire orale remontant &#224; une &#233;poque o&#249; les
humains ne se tenaient pas encore debout sur deux jambes.
La plupart des hommes-l&#233;zards mesurent entre
1,80 m&#232;tres et 2,10 m&#232;tres et p&#232;sent de 100 kg &#224; 125 kg. &lt;br /&gt;&lt;br /&gt;Leurs muscles puissants sont recouverts d’&#233;cailles grises, vertes
ou brunes. Certaines esp&#232;ces poss&#232;dent de petites cr&#234;tes
dorsales ou des collerettes de couleur vive. Ce sont tous
d’excellents nageurs qui se d&#233;placent en agitant leurs
puissantes queues de 1,20 m&#232;tre. Ils sont tout &#224; fait &#224;
l’aise dans l’eau, mais peuvent &#233;galement respirer
&#224; l’air libre. &lt;br /&gt;&lt;br /&gt;Ils retournent syst&#233;matiquement vers les monticules o&#249; ils vivent en groupe pour se reproduire et pour
dormir. Comme leur sang reptilien les rend l&#233;thargiques lorsqu’il
fait froid, la plupart des hommes-l&#233;zards chassent et travaillent
pendant la journ&#233;e et se retirent dans leur demeure la nuit, pour
se pelotonner contre les autres membres de la tribu et partager la
chaleur de larges feux de tourbe.&lt;br /&gt;&lt;br /&gt;Les hommes-l&#233;zards sont g&#233;n&#233;ralement d’alignement Neutre
mais leur comportement distant, leur rejet ferme des &#171; dons &#187;
de la civilisation et leur l&#233;gendaire f&#233;rocit&#233; au combat font que la
plupart des humano&#239;des en ont une pi&#232;tre opinion. Les hommes-l&#233;zards
ont de bonnes raisons d’adopter ces traits cependant, car
leur rythme de reproduction est tr&#232;s faible &#224; c&#244;t&#233; de celui des
humano&#239;des &#224; sang chaud, et les tribus qui ne d&#233;fendraient pas leur
territoire mar&#233;cageux jusqu’&#224; la mort se retrouveraient rapidement
submerg&#233;es par des hordes de mammif&#232;res. &lt;br /&gt;&lt;br /&gt;Quant &#224; leur tendance &#224; consommer les corps des amis et des ennemis d&#233;funts, les hommes-l&#233;zards
la justifient par le bon sens : la vie dans les marais &#233;tant
difficile, ils ne peuvent pas se permettre de gaspiller quoi que ce soit.
L’homme-l&#233;zard pr&#233;sent&#233; ici vit dans un environnement
mar&#233;cageux. On peut trouver des tribus d’hommes-l&#233;zards dans
d’autres milieux, mais ils perdent alors leur vitesse de nage et
gagnent une vitesse d’escalade de 4,50 m&#232;tres.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;&#201;cologie&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;cologie_4&quot; href=&quot;#&#201;cologie_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les hommes-l&#233;zards forment une race antique dont les origines se perdent dans la nuit des temps. Ils disent qu’ils sont aussi &#226;g&#233;s que le monde et qu’ils sont apparus en m&#234;me temps que les dinosaures. &#192; cause de cette croyance, leur culture s’est ancr&#233;e dans ses traditions et s’accroche &#224; des technologies archa&#239;ques. Pourtant, cela ne les emp&#234;che pas de lutter, bien que leur nombre diminue car ils pr&#233;f&#232;rent se retirer au cœur des marais plut&#244;t que d’interagir avec un monde o&#249; les esp&#232;ces &#224; sang chaud se reproduisent bien plus vite qu’eux et les rendent quantit&#233; n&#233;gligeable.&lt;br /&gt;&lt;br /&gt;Les femelles pondent &#224; peine une poign&#233;e d’œufs au cours de leur vie. Ces œufs sont tr&#232;s d&#233;licats et, entre les modifications de l’habitat, la raret&#233; de la nourriture et les pr&#233;dateurs, ils arrivent rarement &#224; terme. En cas de famine, il arrive m&#234;me que la tribu mange une couv&#233;e plut&#244;t que de la laisser &#233;clore et donner naissance &#224; de nouvelles bouches &#224; nourrir.&lt;br /&gt;&lt;br /&gt;Les œufs viables demandent des soins constants. Comme chez de nombreux reptiles, les jeunes encore dans leur coquille changent de sexe en r&#233;ponse aux changements de temp&#233;rature. La tribu manipule souvent ce param&#232;tre pour conserver la parit&#233; sexuelle, un &#233;l&#233;ment essentiel dont d&#233;pend la survie de la prochaine g&#233;n&#233;ration. Contrairement aux œufs d&#233;licats dont ils sont issus, les jeunes hommes-l&#233;zards sont tr&#232;s r&#233;sistants et &#233;closent avec des crocs et des griffes fonctionnels.&lt;br /&gt;&lt;br /&gt;Une race afflig&#233;e d’un taux de reproduction si faible ne peut se permettre de perdre ses membres lors d’une guerre. Les
hommes-l&#233;zards s’allient parfois avec d’autres esp&#232;ces de reptiles ou d’amphibiens, mais veillent &#224; choisir uniquement des cr&#233;atures dont la pr&#233;sence n’appauvrira pas les ressources du territoire. Un unique dragon, un cercle de nagas, un troupeau de dinosaures herbivores… toutes ces cr&#233;atures peuvent cohabiter confortablement avec une tribu d’hommes-l&#233;zards mais si cette derni&#232;re devait partager son domaine avec de nombreux &lt;a class=&quot;pagelink&quot; href=&quot;Grippli-(Race).html&quot; title=&quot;Les gripplis&quot;&gt;gripplis&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;bourbi&#233;rins&lt;/a&gt;, le conflit serait in&#233;vitable.&lt;br /&gt;&lt;br /&gt;&#192; l’exception de l’h&#233;ritier homme-l&#233;zard (voir page 136), la plupart des hommes-l&#233;zards vivent entre 60 et 80 ans. Les m&#226;les et les femelles grandissent toute leur vie et les rares individus qui parviennent &#224; transcender le processus de vieillissement (comme les druides ou les alchimistes de haut niveau) atteignent parfois une taille G, autour de leur premier si&#232;cle. La taille et les connaissances de ces individus leur assurent une place de dirigeant au sein de leur soci&#233;t&#233;, bien qu’ils ne b&#233;n&#233;ficient jamais de la r&#233;v&#233;rence spirituelle r&#233;serv&#233;e aux h&#233;ritiers, consid&#233;r&#233;s comme des vestiges du pass&#233; ressuscit&#233;.&lt;br /&gt;&lt;br /&gt;Un vieil homme-l&#233;zard participe &#224; la vie de la tribu jusqu’&#224; sa mort. Peu de communaut&#233;s ont assez de ressources pour entretenir des membres inactifs, les anciens deviennent donc des professeurs, des gu&#233;risseurs ou des nourrices. M&#234;me les jeunes travaillent d&#232;s qu’ils ont la dext&#233;rit&#233; n&#233;cessaire pour tisser des filets de p&#234;che, pr&#233;parer la nourriture ou surveiller leurs jeunes fr&#232;res et sœurs. Comme ces t&#226;ches sont indispensables &#224; la survie de la tribu, un adulte supervise les jeunes mais ces derniers disposent d’un niveau d’autonomie et de responsabilit&#233; qui d&#233;passe de loin celui des humains de leur &#226;ge.&lt;br /&gt;&lt;br /&gt;La plupart des hommes-l&#233;zards vivent dans des campements robustes construits dans les marais temp&#233;r&#233;s. Pour un &#233;tranger, ces communaut&#233;s semblent sans d&#233;fense, mais en r&#233;alit&#233;, les hommes-l&#233;zards veillent &#224; s’installer dans des portions de rivi&#232;re ou de marais faciles &#224; d&#233;fendre : elles sont dot&#233;es de plusieurs entr&#233;es immerg&#233;es, d’itin&#233;raires de fuite et d’acc&#232;s par voie de terre pour les cr&#233;atures qui ne savent pas nager. Ce type de camp abrite g&#233;n&#233;ralement une seule tribu, qui vit des ressources disponibles &#224; proximit&#233; et lance quelques exp&#233;ditions de chasse au loin en cas de disette. Les hommes-l&#233;zards sont actifs de jour car ils n’ont pas de vision nocturne et pr&#233;f&#232;rent se retirer dans la douce chaleur et la s&#233;curit&#233; de leur foyer une fois la nuit tomb&#233;e.&lt;br /&gt;&lt;br /&gt;Les hommes-l&#233;zards sont des cr&#233;atures tr&#232;s isolationnistes. Ils commercent et s’allient seulement avec les groupes qu’ils connaissent depuis longtemps. M&#234;me s’ils n’&#233;taient pas aussi x&#233;nophobes, ils travaillent tant pour assurer la s&#233;curit&#233; de leur tribu et pour la nourrir qu’ils n’ont gu&#232;re le temps de fraterniser avec des &#233;trangers. Les rencontres avec les hommes-l&#233;zards sont donc br&#232;ves et abruptes, les astuces diplomatiques d’un &#233;missaire ne lui servant &#224; rien face &#224; un chaman qui doit encore pr&#233;parer &#224; manger, lancer des sorts protecteurs sur sa couv&#233;e et gu&#233;rir les plaies de ses guerriers. Pourtant, les gens qui passent assez de temps avec les hommes-l&#233;zards d&#233;couvrent la riche tradition orale de ces &#234;tres qui se transmettent des milliers d’ann&#233;es de savoir et de sagesse.&lt;br /&gt;&lt;br /&gt;Les hommes-l&#233;zards acceptent rarement des &#233;trangers dans leur camp et les rencontrent plut&#244;t dans un campement interm&#233;diaire ou dans un site naturel. Ils n’imposent pas de pratiques religieuses ou culturelles &#224; leurs alli&#233;s ou partenaires commerciaux et ils en attendent autant en retour. En revanche, ils ont des exigences &#233;cologiques qui d&#233;bouchent parfois sur quelques frictions. Les humano&#239;des confondent souvent ces exigences avec des superstitions ou de l’animisme de &#171; sauvage &#187; mais il est bien rare que les hommes-l&#233;zards accordent une signification religieuse &#224; la terre. Quand ils d&#233;cident de prot&#233;ger un site naturel, c’est afin de pr&#233;server leur environnement car le moindre changement de l’habitat peut avoir des cons&#233;quences mortelles.&lt;br /&gt;&lt;br /&gt;Les hommes-l&#233;zards ne sont pas mal&#233;fiques mais leur sens pratique d&#233;go&#251;te parfois les autres races, en particulier quand il les pousse &#224; s’adonner au cannibalisme. Pour un homme-l&#233;zard, de la viande reste de la viande et, pendant une p&#233;riode de famine, ce serait une insulte aux guerriers tomb&#233;s au combat que de laisser pourrir leur chair plut&#244;t que d’en nourrir la tribu.&lt;br /&gt;&lt;br /&gt;Ce pragmatisme inn&#233; se manifeste aussi dans leurs relations sociales. Il y a autant de crimes, de machinations politiques et de querelles internes dans les campements d’hommes-l&#233;zards que dans les communaut&#233;s humaines, mais leur sens des lois naturelles les emp&#234;che de sombrer dans le chaos. La justice tribale est &#233;quitable et rapide, la plupart des d&#233;saccords se r&#233;glant par un combat sans mort entre les partis concern&#233;s. Parfois, ces disputes se soldent par un duel par procuration, chaque camp se choisissant un champion.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Nouvelles r&#232;gles raciales&lt;a class=&quot;headeranchor&quot; id=&quot;Nouvelles_r&#232;gles_raciales_5&quot; href=&quot;#Nouvelles_r&#232;gles_raciales_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les r&#232;gles suivantes pr&#233;sentent un arch&#233;type, une mal&#233;diction d’oracle, des dons et des sorts tr&#232;s pris&#233;s des hommes-l&#233;zards.
&lt;h3 class=&quot;separator&quot;&gt;Dons&lt;a class=&quot;headeranchor&quot; id=&quot;Dons_0&quot; href=&quot;#Dons_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici quelques dons am&#233;liorant les capacit&#233;s naturelles des hommes-l&#233;zards, bien que l’&lt;a class=&quot;pagelink&quot; href=&quot;Adaptation-Aquatique.html&quot; title=&quot;Adaptation aquatique&quot;&gt;Adaptation aquatique&lt;/a&gt; soit aussi accessible aux individus mut&#233;s ou uniques de n’importe quelle race, &#224; condition de remplir les conditions requises.
&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche filtrable&quot; WIDTH=&quot;100%&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Dons&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Src&lt;/td&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Conditions&lt;/td&gt;&lt;td WIDTH=&quot;37%&quot;&gt;Avantages&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adaptation-Aquatique.html&quot; title=&quot;Adaptation aquatique&quot;&gt;Adaptation aquatique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Retenir-Son-Souffle-(Capacit&#233;).html&quot; title=&quot;Retenir son souffle (Ext)&quot;&gt;retenir son souffle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Respire aussi bien l&#39;eau que l&#39;air&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dangereuse-Queue.html&quot; title=&quot;Dangereuse queue&quot;&gt;Dangereuse queue&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +5, &lt;a class=&quot;pagelink&quot; href=&quot;Homme-L&#233;zard.html&quot; title=&quot;Homme-l&#233;zard&quot;&gt;homme-l&#233;zard&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Gain d&#39;une attaque de queue&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nage-Rapide.html&quot; title=&quot;Nage rapide&quot;&gt;Nage rapide&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homme-L&#233;zard.html&quot; title=&quot;Homme-l&#233;zard&quot;&gt;Homme-l&#233;zard&lt;/a&gt;, vitesse de nage&lt;/td&gt;&lt;td&gt;+4,5 m &#224; la vitesse de nage&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;
&lt;div class=&quot;row ligne&quot; style=&quot;&quot;&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
